SourceCode.Declaration:
/// <summary>
/// getVariance's request (supervisor only). UserId must be a cycle-count supervisor
/// (HSMobileOpsUser.IsCycleCountSupervisor).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountVarianceRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             userId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}
